steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        projects(name: \"Checkout Redesign\") {
          nodes {
            id
            name
            lead {
              id
              name
              email
            }
            milestones {
              nodes {
                id
                name
                targetDate
              }
            }
          }
        }
      }
    '
  }'
